    summary: 'Мамонтенок Пушистик пробуждается после тысячелетнего сна в ледяной пустыне и отправляется на поиски своей мамы. Говорят, ее можно найти в далекой и загадочной Африке. Но Африка далеко, добраться туда крайне сложно, а единственный спутник мамонтенка — птенец Тупик, который мечтает прочитать свой рэп на конкурсе «Африка ищет таланты». Вдвоем им предстоит преодолеть множество испытаний: пересечь океан на льдине, сбежать от кровожадных крокодилов, победить коварных гиен, играть свою музыку перед самыми разными зрителями, а главное — научиться быть друзьями и понять, что дружба — это ответственность и поддержка. Синема 5 ТРК "Парк Хаус", пр-кт Хусаина Ямашева, д 46/33, ТРК "Парк Хаус", 2 этаж. В афише 6 сеансов.',
