    summary: 'Спустя 30 лет после начала истории группы «Руки Вверх!» Сергей Жуков вместе с детьми возвращается к воспоминаниям о своей молодости — первой любви, первых больших мечтах, дружбе, семье и пути к сцене. Это история не только о музыке и популярности, но и о жизни за пределами софитов — о людях, которые влюблялись, ошибались, взрослели и пытались сохранить самое важное рядом с собой. Синема 5 Киносфера IMAX ТЦ "Капитолий" Ленинградский, ул. Правобережная, д. 1, корп. Б, ТЦ "Капитолий". В афише 4 сеанса.',
